Utilizing group-theoretic arguments, Weyl demonstrated \cite{Weyl1950} 
\begin{align}\label{PhysOrigin_CCR}
	\left| \langle x \ket{p} \right|^2 = \mbox{const} \Longleftrightarrow  \commut{ \hat{x}, \hat{p} } = i \hbar,
\end{align}
(for alternative derivations see Refs. \cite{Schwinger2003, Bondar2011a}).

\begin{align}\label{PhysOrigin_CCR}
	\left| \langle x \ket{p} \right|^2 = \mbox{const} \Longleftrightarrow  \commut{ \hat{x}, \hat{p} } = i \hbar,
\end{align}

Thus, in the literature on finite-dimensional quantum mechanics, the coordinate and momentum operators are usually defined as those whose eigenvectors obey
\begin{align}\label{Deff_PX_as_MUBS}
	\langle x_n \ket{p_k} = \exp(i2\pi n k /N) / \sqrt{N}, 
\end{align}
where $n,k = -j, -j+1, \ldots, j-1, j$, $j =2N+1$, $\hat{x} \ket{x_n} = an\ket{x_n}$, $\hat{p} \ket{p_k} = 2\pi \hbar k/(aN) \ket{p_k}$, and $N$ is the Hilbert space's dimension (see Ref. \cite{DelaTorre2003a} for a detailed description of the notation).

\begin{align}\label{Deff_PX_as_MUBS}
	\langle x_n \ket{p_k} = \exp(i2\pi n k /N) / \sqrt{N}, 
\end{align}

The finite-dimensional Schr\"{o}dinger equation is
\begin{align}\label{Sch_Eq_General_Form}
	i\hbar \ket{d\Psi(t)/dt} = \hat{H} \ket{\Psi(t)},
\end{align}
where there are at least two independent ways of introducing $\hat{H}$.

\begin{align}\label{Sch_Eq_General_Form}
	i\hbar \ket{d\Psi(t)/dt} = \hat{H} \ket{\Psi(t)},
\end{align}

First, the Hamiltonian   
\begin{align}\label{Infinite_Dim_Form_Hamiltonian}
	\hat{H} = \hat{p}^2/(2m) + U(\hat{x})
\end{align}
can be adapted with the specification that $\hat{x}$ and $\hat{p}$ are defined by Eq. (\ref{Deff_PX_as_MUBS}).

\begin{align}\label{Infinite_Dim_Form_Hamiltonian}
	\hat{H} = \hat{p}^2/(2m) + U(\hat{x})
\end{align}

In Ref. \cite{Bondar2011c}, along with a number of other applications, we utilized this method to infer the classical Liouville and Schr\"{o}dinger equations from the Ehrenfest theorems, 
\begin{align}
	m\frac{d}{dt} \bra{\Psi(t)} \hat{x} \ket{\Psi(t)} & = \bra{\Psi(t)} \hat{p} \ket{\Psi(t)}, 	\label{EhrenfestTh1} \\
	\frac{d}{dt} \bra{\Psi(t)} \hat{p} \ket{\Psi(t)} & = \bra{\Psi(t)} -U'(\hat{x}) \ket{\Psi(t)},	\label{EhrenfestTh2}
\end{align}
by assuming that the coordinate $\hat{x}$ and momentum $\hat{p}$ commuted in the former case and obeyed the canonical commutation relation in the latter.

\begin{align}
	m\frac{d}{dt} \bra{\Psi(t)} \hat{x} \ket{\Psi(t)} & = \bra{\Psi(t)} \hat{p} \ket{\Psi(t)}, 	\label{EhrenfestTh1} \\
	\frac{d}{dt} \bra{\Psi(t)} \hat{p} \ket{\Psi(t)} & = \bra{\Psi(t)} -U'(\hat{x}) \ket{\Psi(t)},	\label{EhrenfestTh2}
\end{align}

Closely following Ref. \cite{Bondar2011c}, we apply ODM to Eqs. (\ref{EhrenfestTh1}) and (\ref{EhrenfestTh2}): Stone's theorem (see, e.g., Ref. \cite{Reed1980, Araujo2008})  
guarantees the uniqueness of the Hermitian operator $\hat{H}$ in Eq. (\ref{Sch_Eq_General_Form}). Applying the chain rule to the left-hand side of Eqs. (\ref{EhrenfestTh1}) and (\ref{EhrenfestTh2}) and then utilizing Eq. (\ref{Sch_Eq_General_Form}), one obtains
\begin{align}
	im \commut{\hat{H}, \hat{x}} &= \hbar \hat{p},  \label{First_CommutEq_for_Hamiltonian} \\
	i\commut{\hat{H}, \hat{p}} &= -\hbar U'(\hat{x}). \label{Second_CommutEq_for_Hamiltonian}
\end{align}    
We shall demonstrate below that Eqs. (\ref{First_CommutEq_for_Hamiltonian}) and (\ref{Second_CommutEq_for_Hamiltonian}) cannot be satisfied by non-trivial finite-dimensional operators.

\begin{align}
	im \commut{\hat{H}, \hat{x}} &= \hbar \hat{p},  \label{First_CommutEq_for_Hamiltonian} \\
	i\commut{\hat{H}, \hat{p}} &= -\hbar U'(\hat{x}). \label{Second_CommutEq_for_Hamiltonian}
\end{align}

Let $\ket{E_n}$ denote a joint eigenvector of $\hat{H}$ and $\hat{p}$ such that $\hat{H} \ket{E_n} = E_n \ket{E_n}$ and $\hat{p} \ket{E_n} = p_n \ket{E_n}$. Assuming that $i \commut{ \hat{H}, \hat{x} } = \hat{p}$, one obtains 
\begin{align}
	i \bra{E_n} \commut{ \hat{H}, \hat{x} } \ket{E_m} = i (E_n - E_m) \bra{E_n} \hat{x} \ket{E_m} = p_m \langle E_n \ket{E_m}, 
\end{align}
$\forall n,m$.
The special case of this identity, when $n=m$, reads $p_m = 0$, $\forall m$. This contradicts the assumption that $\hat{p}$ is a non-zero matrix.

\begin{align}
		i \bra{E_n} \commut{ \hat{H}, \hat{x} } \ket{E_m} = i (E_n - E_m) \bra{E_n} \hat{x} \ket{E_m} = p_m \langle E_n \ket{E_m}, 
	\end{align}

\label{NoDiffAsCommutator_Theorem}
	There are no finite-dimensional operators $\hat{A}$ and $\hat{B}$ such that 
	\begin{align}\label{NoDiffAsCommutator_Eq1}
		\commut{ f(\hat{A}), \hat{B} } =  f'(\hat{A})
	\end{align}
	for any ``good'' function $f(z)$.

\begin{align}\label{NoDiffAsCommutator_Eq1}
		\commut{ f(\hat{A}), \hat{B} } =  f'(\hat{A})
	\end{align}

Let a function of an operator be defined as  (see, e.g., Ref. \cite{Nazaikinskii1992})
\begin{align}
	f(\hat{A}) \coloneqq \int g(k) e^{ik\hat{A}} dk, \quad f'(\hat{A}) \coloneqq \int ik g(k) e^{ik\hat{A}} dk, \notag
\end{align}
where $g(k)$ is the Fourier transform of a function $f(z)$. The correctness of Eq. (\ref{NoDiffAsCommutator_Eq1}) implies 
\begin{align}
	\commut{ e^{ik\hat{A}}, \hat{B} } = ik e^{ik\hat{A}}.
\end{align}
Differentiating the last identity with respect to $k$ and setting $k=0$, we reach the contradiction $\commut{ \hat{A}, \hat{B} } = 1$.

\begin{align}
		f(\hat{A}) \coloneqq \int g(k) e^{ik\hat{A}} dk, \quad f'(\hat{A}) \coloneqq \int ik g(k) e^{ik\hat{A}} dk, \notag
	\end{align}

\begin{align}
		\commut{ e^{ik\hat{A}}, \hat{B} } = ik e^{ik\hat{A}}.
	\end{align}

Assuming $\hat{x}$ is Hermitian and has a non-degenerate spectrum, the solution of Eq. (\ref{First_CommutEq_for_Hamiltonian}) is
\begin{align}\label{Ehrenfest_Compartible_GeneralHamiltonian}
	\bra{x_k} \hat{H}^{\star} \ket{x_l} = \left\{
		\begin{array}{ll}
			U(x_k) + C & \mbox{if } k=l \\
			\frac{i \hbar \bra{x_k} \hat{p} \ket{x_l} }{m(x_k - x_l)} &\mbox{otherwise}
		\end{array}
	\right.
\end{align}
where $\hat{x} \ket{x_l} = x_l \ket{x_l}$ and $C$ is an arbitrary real constant.

\begin{align}\label{Ehrenfest_Compartible_GeneralHamiltonian}
	\bra{x_k} \hat{H}^{\star} \ket{x_l} = \left\{
		\begin{array}{ll}
			U(x_k) + C & \mbox{if } k=l \\
			\frac{i \hbar \bra{x_k} \hat{p} \ket{x_l} }{m(x_k - x_l)} &\mbox{otherwise}
		\end{array}
	\right.
\end{align}

Then, the corresponding Hamiltonian from Eq. (\ref{Ehrenfest_Compartible_GeneralHamiltonian}), 
\begin{align}\label{FiniteDiff_approx_Hamiltonian}
	\bra{x_k} \hat{H}^{\star}_{fd} \ket{x_l} = \frac{-\hbar^2}{2ma^2} \left( \delta_{l,k+1} + \delta_{l,k-1} \right) +  [U(x_k) + C]\delta_{l,k},
\end{align}
satisfying the Ehrenfest theorem (\ref{EhrenfestTh1}), takes the form of the simplest finite-difference approximation for the differential operator: $-\hbar^2/(2m) d^2/dx^2 + U(x)$.

\begin{align}\label{FiniteDiff_approx_Hamiltonian}
	\bra{x_k} \hat{H}^{\star}_{fd} \ket{x_l} = \frac{-\hbar^2}{2ma^2} \left( \delta_{l,k+1} + \delta_{l,k-1} \right) +  [U(x_k) + C]\delta_{l,k},
\end{align}

Figures \ref{Fig_SpectraComparison} and \ref{Fig_EigenvectorComparison} depict the eigenvalues and the twentieth eigenvector of the Hamiltonians $\hat{H}^{\star}_{fd}$, $\hat{H}_{mub}^{\star}$, and  $\hat{H}_{mub}$ for the oscillator, 
\begin{align}\label{SingularHarmonicOscil_Hamiltonian}
	U(x) = \frac{\omega^2}{8} x^2  + \frac{g}{4x^2}, \qquad 0 \leqslant x < \infty, 
\end{align}
which is exactly solvable in the infinite-dimensional case \cite{Calogero1969}. The values of the coordinate step, $a$, for $\hat{H}_{mub}^{\star}$ and $\hat{H}_{mub}$ are selected to minimize the largest eigenvalues of each Hamiltonian, which leads to the spectra of  $\hat{H}_{mub}^{\star}$ and $\hat{H}_{mub}$ (for a finite $N$) best fitting the exact energy in the infinite-dimensional case [see Figs. \ref{Fig_SpectraComparison}(b) and \ref{Fig_SpectraComparison}(c)]. However, the same recipe applied to $\hat{H}_{fd}^{\star}$ does not provide a good fit, and the step size for $\hat{H}_{fd}^{\star}$ is manually adjusted to match the exact energies. This exercise  demonstrates [Fig. \ref{Fig_EigenvectorComparison}(a)] that even though the Hamiltonian $\hat{H}_{fd}^{\star}$ reproduces the exact energy better than either $\hat{H}_{mub}^{\star}$ or $\hat{H}_{mub}$, it yields poor quality excited states. Finally, note that the Hamiltonian $\hat{H}_{mub}^{\star}$, satisfying Ehrenfest theorem (\ref{EhrenfestTh1}), provides results of the same quality as $\hat{H}_{mub}$, violating Eq.  (\ref{EhrenfestTh1}). These observations indicate that there is no correlation between the  numerical calculations' accuracy and the Ehrenfest theorem's validity. Note, however, that any disagreement between the exact and numerical results in Figs. \ref{Fig_SpectraComparison} and \ref{Fig_EigenvectorComparison} will exponentially increase with the number of spatial dimensions.

\begin{align}\label{SingularHarmonicOscil_Hamiltonian}
	U(x) = \frac{\omega^2}{8} x^2  + \frac{g}{4x^2}, \qquad 0 \leqslant x < \infty, 
\end{align}

First, re-applying ODM to Eqs. (\ref{EhrenfestTh1}) and (\ref{EhrenfestTh2}) with the condition $\hat{H} \neq \hat{H}^{\dagger}$, the following generalizations of Eqs. (\ref{First_CommutEq_for_Hamiltonian}) and (\ref{Second_CommutEq_for_Hamiltonian}) are obtained:
\begin{align}
	im ( \hat{H}^{\dagger} \hat{x} - \hat{x} \hat{H} ) = \hbar \hat{p}, \quad 
	i (  \hat{H}^{\dagger} \hat{p} - \hat{p} \hat{H} ) = -\hbar U'(\hat{x}).   
\end{align}

\begin{align}
	im ( \hat{H}^{\dagger} \hat{x} - \hat{x} \hat{H} ) = \hbar \hat{p}, \quad 
	i (  \hat{H}^{\dagger} \hat{p} - \hat{p} \hat{H} ) = -\hbar U'(\hat{x}).   
\end{align}

\label{NonHermitian_Lemma1}
	Assume that $\hat{x}$, $\hat{p}$, and $\hat{H}$ are bounded. If $\sigma(\hat{H}^{\dagger}) \cap \sigma(\hat{H}) = \emptyset$ and
	\begin{align}
		& im ( \hat{H}^{\dagger} \hat{x} - \hat{x} \hat{H} ) = \hbar \hat{p}, \label{First_OperEq_for_NonHer_FreeHamiltonian} \\
		& \hat{H}^{\dagger} \hat{p} = \hat{p} \hat{H}, \label{Second_OperEq_for_NonHer_FreeHamiltonian}
	\end{align}
	then $\hat{p} = \hat{x} = 0$. Here, $\sigma(\hat{A})$ denotes the spectrum of an operator $\hat{A}$.

\begin{align}
		& im ( \hat{H}^{\dagger} \hat{x} - \hat{x} \hat{H} ) = \hbar \hat{p}, \label{First_OperEq_for_NonHer_FreeHamiltonian} \\
		& \hat{H}^{\dagger} \hat{p} = \hat{p} \hat{H}, \label{Second_OperEq_for_NonHer_FreeHamiltonian}
	\end{align}

First, we employ the Rosenblum theorem \cite{Rosenblum1956} (see Theorem 9.3 in Ref. \cite{Bhatia1997}) to Eq. (\ref{First_OperEq_for_NonHer_FreeHamiltonian}) and then employ Eq. (\ref{Second_OperEq_for_NonHer_FreeHamiltonian}) to show 
\begin{align}
	im\hat{x} =& \frac{\hbar}{2\pi i} \oint_{\Gamma} d\xi ( \hat{H}^{\dagger} - \xi )^{-1} \hat{p} ( \hat{H} - \xi )^{-1} \notag\\
		=&  \frac{\hbar}{2\pi i} \hat{p} \oint_{\Gamma} d\xi ( \hat{H} - \xi )^{-2}  = 0,
\end{align}
where $\Gamma$ denotes a union of closed contours in the complex plane with total winding numbers $1$ around $\sigma(\hat{H}^{\dagger})$ and $0$ around $\sigma(\hat{H})$.

\begin{align}
		im\hat{x} =& \frac{\hbar}{2\pi i} \oint_{\Gamma} d\xi ( \hat{H}^{\dagger} - \xi )^{-1} \hat{p} ( \hat{H} - \xi )^{-1} \notag\\
			=&  \frac{\hbar}{2\pi i} \hat{p} \oint_{\Gamma} d\xi ( \hat{H} - \xi )^{-2}  = 0,
	\end{align}

Suppose $\hat{p} \neq 0$. According to Lyapunov stability theory \cite{Lyapunov1992}, the second assumption implies that $\Im(E_n) \leqslant 0$, $\forall n\in I$. Lemma \ref{NonHermitian_Lemma1} guarantees that $\hat{H}$ has at least a single real eigenvalue. Introduce $R \coloneqq \{ n \in I \, | \, \Im(E_n) = 0 \} \neq \emptyset$ -- the set of the real eigenvalues' indices. 
``Sandwiching'' Eqs. (\ref{First_OperEq_for_NonHer_FreeHamiltonian}) and (\ref{Second_OperEq_for_NonHer_FreeHamiltonian}) leads to
\begin{align}
	& im ( E_k^* - E_l ) \bra{E_k} \hat{x} \ket{E_l} = \hbar \bra{E_k} \hat{p} \ket{E_l}, \label{NonHermTh1_Eq1}\\
	& ( E_k^* - E_l ) \bra{E_k} \hat{p} \ket{E_l} = 0, \qquad \forall k,l \in I. \label{NonHermTh1_Eq2}
\end{align}
According to Eq. (\ref{NonHermTh1_Eq2}), $\bra{E_k} \hat{p} \ket{E_l}$ may be non-zero only for $(k,l) \in Q \coloneqq \{ (k,l) \in R \times R \, | \, E_k = E_l \}$. However, Eq. (\ref{NonHermTh1_Eq1}) enforces $\bra{E_k} \hat{p} \ket{E_l} = 0$, $\forall (k,l) \in Q$. Therefore, we reach the contradiction $\hat{p} = 0$.

\begin{align}
		& im ( E_k^* - E_l ) \bra{E_k} \hat{x} \ket{E_l} = \hbar \bra{E_k} \hat{p} \ket{E_l}, \label{NonHermTh1_Eq1}\\
		& ( E_k^* - E_l ) \bra{E_k} \hat{p} \ket{E_l} = 0, \qquad \forall k,l \in I. \label{NonHermTh1_Eq2}
	\end{align}
